def test_a_grader_that_writes_a_good_brief_then_fails_is_rejected(fixture_root):
    """A non-zero exit is a rejection even when the output file is perfectly valid, and the
    grader's own stderr is what tells the author why."""
    _grader(
        "open(sys.argv[3], 'w').write(json.dumps({'name': 'c', 'replicas': 2}));"
        " raise SystemExit('the grader gave up')",
        head="import json, sys",
    )
    with pytest.raises(manifest.Rejected, match="the grader gave up"):
        manifest.generate_brief(catalogue.tasks()[SLUG], 7)


def test_render_fills_placeholders_and_survives_doubled_braces():
    assert manifest.render("a {name} b", {"name": "x"}) == "a x b"
    assert manifest.render("a {{literal}} b", {}) == "a {literal} b"


@pytest.mark.parametrize(
    "template",
    [
        "{missing}",
        "{name.nope}",
        "{replicas[0]}",
        "{name:d}",
        "{0}",
        "{name",
        "{}",
        "{name!r}",
        "{name:>1}",
        "{name:{name}}",
    ],
)
def test_a_template_the_brief_does_not_fit_is_rejected(template):
    """Every placeholder mistake a task author can make is a `Rejected`, never a traceback
    out of the server."""
    with pytest.raises(manifest.Rejected):
        manifest.render(template, {"name": "checkout", "replicas": 2})


def test_a_template_cannot_allocate_before_it_is_refused():
    """The width is refused on sight, so `format` never allocates a terabyte for it."""
    with pytest.raises(manifest.Rejected, match="plain name"):
        manifest.render("{name:>1000000000000}", {"name": "x"})


def test_a_filled_spec_is_still_bounded():
    with pytest.raises(manifest.Rejected, match="too long"):
        manifest.render("{name}", {"name": "x" * (manifest.MAX_SPEC_CHARS + 1)})


def test_the_grader_revision_moves_when_either_file_behind_a_brief_does(fixture_root):
    """Which generator produced a stored brief: both files it takes to make one count."""
    meta = catalogue.tasks()[SLUG]
    first = manifest.grader_revision(meta)
    assert first == manifest.grader_revision(meta) and len(first) == 12
    _grader("return {'name': 'checkout'}")
    second = manifest.grader_revision(meta)
    assert second != first, "a new grade.py is a new generator"
    (settings.tasks_dir / SLUG / "solution.yaml").write_text(
        "kind: Deployment\n", encoding="utf-8"
    )
    assert manifest.grader_revision(meta) not in (first, second), (
        "a new solution.yaml is a new generator too"
    )


def test_opening_persists_the_brief_and_the_rendered_spec(fixture_root):
    meta = catalogue.tasks()[SLUG]
    with state.writing() as st:
        o = attempts.open_attempt(st, SLUG, meta)
    assert o["brief"]["name"] in ("checkout", "billing")
    assert f"named `{o['brief']['name']}`" in o["spec_md"]
    assert "{name}" not in o["spec_md"]
    assert o["brief_revision"] == manifest.grader_revision(meta)


def test_an_edited_readme_does_not_change_an_open_sitting(fixture_root):
    with state.writing() as st:
        first = attempts.open_attempt(st, SLUG, catalogue.tasks()[SLUG])["spec_md"]
    readme = settings.tasks_dir / SLUG / "README.md"
    readme.write_text(
        readme.read_text(encoding="utf-8").replace("Because", "CHANGED"),
        encoding="utf-8",
    )
    meta = catalogue.tasks()[SLUG]
    assert "CHANGED" in meta["spec_md"], "the catalogue never re-read the README"
    with state.writing() as st:
        again = attempts.open_attempt(st, SLUG, meta)
    assert again["spec_md"] == first
    # the serve path as well as the store: `api._payload` asks the kind, not the README
    assert kinds.of(meta).spec(meta, again) == first
    # nothing open: the README as written, placeholders and all
    assert kinds.of(meta).spec(meta, None) == meta["spec_md"]


