def test_the_task_page_is_served_the_sitting_spec_not_the_readme(fixture_root):
    """The serve path end to end: `api._payload` asks the kind which guidance to show."""

    async def drive():
        async with httpx.AsyncClient(
            transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1"
        ) as api:
            closed = (await api.get(f"/api/task/{SLUG}")).json()["spec_md"]
            assert "{name}" in closed, "nothing open, so the README as written"
            opened = (await api.post(f"/api/task/{SLUG}/open")).json()["spec_md"]
            assert "{name}" not in opened
            assert (await api.get(f"/api/task/{SLUG}")).json()["spec_md"] == opened

    asyncio.run(drive())


def test_a_manifest_run_is_graded_by_its_own_kind(fixture_root, monkeypatch):
    """`api.run_task` already holds a kind. Grading through anything else grades a
    learner's YAML as if it were Python, and reports "no tests ran" as a wrong answer."""
    seen = []

    def spy(self, meta, o, src):
        seen.append(o["brief"])
        return True, {
            "headline": [],
            "output": "",
            "printed": "",
            "case": None,
            "diagnostics": [],
        }

    monkeypatch.setattr(kinds._Manifest, "grade", spy, raising=False)

    async def drive():
        async with httpx.AsyncClient(
            transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1"
        ) as api:
            opened = (await api.post(f"/api/task/{SLUG}/open")).json()
            reply = await api.post(
                f"/api/task/{SLUG}/run",
                json={
                    "code": "kind: Deployment\n",
                    "etag": opened["etag"],
                    "submit": False,
                },
            )
            assert reply.status_code == 200, reply.text
            assert reply.json()["passed"] is True

    asyncio.run(drive())
    assert seen and seen[0]["name"] in ("checkout", "billing")


def test_grader_revision_is_not_a_raw_concatenation(fixture_root):
    """Two files that concatenate to the same bytes must not share a revision: a digest
    per file is what keeps a change in one from being cancelled by a change in the other."""
    folder = settings.tasks_dir / SLUG
    revisions = set()
    for grade, solution in ((b"ab", b"c"), (b"a", b"bc")):
        (folder / "grade.py").write_bytes(grade)
        (folder / "solution.yaml").write_bytes(solution)
        revisions.add(manifest.grader_revision({"dir": folder}))
    assert len(revisions) == 2, "the two files were concatenated, not hashed apart"


