def test_the_manifest_solution_reveal_uses_the_stored_brief(fixture_root):
    async def drive():
        async with httpx.AsyncClient(
            transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1"
        ) as api:
            opened = await api.post(f"/api/task/{SLUG}/open")
            assert opened.status_code == 200, opened.text
            assert opened.json()["reference"] is None
            locked = await api.post(f"/api/task/{SLUG}/solution")
            assert locked.status_code == 423, locked.text
            with state.writing() as st:
                o = st["open"][SLUG]
                o.update(attempts=3, active=600, brief={"name": "no", "replicas": 2})
            revealed = await api.post(f"/api/task/{SLUG}/solution")
            assert revealed.status_code == 200, revealed.text
            doc = yaml.safe_load(revealed.json()["reference"])
            assert doc["metadata"]["name"] == "no"
            assert doc["spec"]["replicas"] == 2
            page = await api.get(f"/api/task/{SLUG}")
            assert page.json()["reference"] == revealed.json()["reference"]

    asyncio.run(drive())


def test_a_manifest_pass_returns_its_reference_and_archives_its_revision(
    stubbed_kubeconform,
):
    async def drive():
        async with httpx.AsyncClient(
            transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1"
        ) as api:
            opened = await api.post(f"/api/task/{SLUG}/open")
            assert opened.status_code == 200, opened.text
            o = state.load()["open"][SLUG]
            brief = o["brief"]
            # the answer key itself, rather than a hand-written manifest that would have to
            # be kept schema-valid here as well as in the fixture
            code = manifest.render_solution(meta_for(), brief)
            reply = await api.post(
                f"/api/task/{SLUG}/run",
                json={"code": code, "etag": opened.json()["etag"], "submit": True},
            )
            assert reply.status_code == 200, reply.text
            assert reply.json()["passed"] is True
            assert yaml.safe_load(reply.json()["reference"]) == yaml.safe_load(code)
            saved = state.load()
            assert SLUG not in saved["open"]
            # what judged the pass, which is more than what asked the question: the
            # validator and the schemas decide a manifest verdict too
            assert saved["archive"][SLUG][-1]["revision"] == manifest.fingerprint(
                meta_for()
            )
            assert o["brief_revision"] == manifest.grader_revision(meta_for())
            assert meta_for()["path"].read_text(encoding="utf-8") == ""
            closed = await api.get(f"/api/task/{SLUG}")
            assert closed.status_code == 200, closed.text
            assert closed.json()["status"] == "done"
            # a refresh after the pass still shows the question it asked and its answer
            assert closed.json()["reference"] == reply.json()["reference"]
            assert closed.json()["spec_md"] == o["spec_md"]
            archived = closed.json()["archive"][-1]
            assert archived["kubernetes"] == tools.KUBERNETES_VERSION
            assert "python" not in archived

    asyncio.run(drive())


def test_a_solution_that_will_not_render_does_not_cost_the_learner_the_pass(
    stubbed_kubeconform,
):
    """An answer key that cannot render is the task's bug. Raising here once cost a correct
    submission its pass: `kind.reference` runs inside the same transaction as `record_pass`,
    so the whole thing rolled back and retrying failed forever. `doctor` reports such a task;
    the run still passes, without a reference."""
    solution = settings.tasks_dir / SLUG / "solution.yaml"
    solution.write_text(
        solution.read_text(encoding="utf-8").replace("name: {name}", "name: x-{name}"),
        encoding="utf-8",
    )

    async def drive():
        async with httpx.AsyncClient(
            transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1"
        ) as api:
            opened = (await api.post(f"/api/task/{SLUG}/open")).json()
            b = state.load()["open"][SLUG]["brief"]
            correct = (
                "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n"
                f"  name: {b['name']}\nspec:\n  replicas: {b['replicas']}\n"
            )
            done = await api.post(
                f"/api/task/{SLUG}/run",
                json={"code": correct, "etag": opened["etag"], "submit": True},
            )
            assert done.status_code == 200, done.text
            assert done.json()["passed"], done.text
            assert done.json()["reference"] is None, "no key, but the pass stands"
            assert SLUG not in state.load()["open"], "the sitting closed"

    asyncio.run(drive())


def test_a_grader_upgraded_under_a_live_sitting_still_grades_its_brief(
    stubbed_kubeconform,
):
    """A new grader revision is not a new question: the stored brief is still what the
    learner was shown, so a compatible grader keeps grading it."""
    meta = meta_for()
    o = kinds.of(meta).opening(meta, 1)
    grader = settings.tasks_dir / SLUG / "grade.py"
    grader.write_text(grader.read_text(encoding="utf-8") + "\n# reworded\n", "utf-8")
    assert o["brief_revision"] != manifest.grader_revision(meta_for())
    code = manifest.render_solution(meta_for(), o["brief"])
    (settings.tasks_dir / SLUG / "task.yaml").write_text(code, encoding="utf-8")
    passed, detail = kinds.of(meta_for()).grade(meta_for(), o, code)
    assert passed, detail["headline"]


def test_a_grader_that_cannot_read_the_brief_is_not_the_learner_s_fault(
    stubbed_kubeconform,
):
    """An upgrade whose check() no longer reads a stored brief crashes rather than asserts,
    and that crash is refused as infrastructure instead of charged as a failed attempt."""
    (settings.tasks_dir / SLUG / "task.yaml").write_text(CORRECT, encoding="utf-8")
    (settings.tasks_dir / SLUG / "grade.py").write_text(
        "def brief(r):\n    return {}\n\n\ndef check(doc, b):\n    b['ports']\n",
        encoding="utf-8",
    )
    with pytest.raises(manifest.Rejected, match="KeyError"):
        runner.run_manifest(meta_for(), BRIEF)


def test_a_second_document_can_still_be_saved_while_it_is_being_typed(fixture_root):
    """Saving only asks that it parses, and a multi document stream does. Rejecting it here
    made autosave 400 on every keystroke of a second document, and hid the grader's own
    "expected one document" message behind a PyYAML sentence fragment."""
    two = "apiVersion: v1\nkind: Pod\n---\napiVersion: v1\nkind: Service\n"
    assert kinds.of(meta_for()).validate(two, "") == two
    with pytest.raises(kinds.Invalid):
        kinds.of(meta_for()).validate("a:\n  - [unclosed\n", "")


MULTI = (
    "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: checkout\n"
    "spec:\n  replicas: 3\n---\n"
    "apiVersion: v1\nkind: Pod\nmetadata:\n  name: app\n"
)


def _multi_grader():
    """Swap the fixture task's grader for one that asks for several objects in one file."""
    (settings.tasks_dir / SLUG / "grade.py").write_text(
        "def brief(r):\n"
        "    return {}\n"
        "\n"
        "\n"
        "def check_many(docs, b):\n"
        "    assert [d['kind'] for d in docs] == ['Deployment', 'Pod'], 'kinds'\n"
        "    assert docs[1]['metadata']['name'] == 'app', 'name'\n",
        encoding="utf-8",
    )


def test_a_grader_with_check_many_grades_every_document(stubbed_kubeconform):
    """A task whose answer is several objects in one file is graded on all of them. The
    one-document refusal only belongs to graders still defining `check` alone."""
    _multi_grader()
    passed, headline = _submit(MULTI)
    assert passed, headline


def test_a_check_many_grader_says_which_requirement_missed(stubbed_kubeconform):
    _multi_grader()
    passed, headline = _submit(MULTI.replace("name: app", "name: other"))
    assert not passed and "name" in headline


def test_a_stray_separator_is_not_a_document(stubbed_kubeconform):
    """A trailing `---` makes PyYAML see one more, empty document. kubectl shrugs at it;
    here it is refused by name, because a learner who shipped it to a cluster would get a
    blank object in `kubectl get` and no error at all."""
    _multi_grader()
    passed, headline = _submit(MULTI + "\n---\n")
    assert not passed and "document 3 is not a mapping" in headline
